WITH src AS (SELECT *, TRIM(supplier_name) AS clean_supplier_name FROM suppliers WHERE (country != 'SG' AND LOWER(TRIM(supplier_name)) = 'eurogoods gmbh') OR country = 'UK'), suppliers_stats AS (SELECT country, ROUND((100 * SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_us, SUM(CASE WHEN country = 'DE' THEN rating ELSE 0 END) AS de_rating FROM src GROUP BY country) SELECT country, pct_us, de_rating FROM suppliers_stats ORDER BY de_rating DESC
